import React, { useRef, useEffect } from 'react';

const BoundingBoxCanvas = ({ imageUrl, boxes, labelColors, sliderConfidence }) => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const context = canvas.getContext('2d');
    const image = new Image();

    image.onload = () => {
      canvas.width = 640;
      canvas.height = 640;
      context.drawImage(image, 0, 0, 640, 640);

      boxes.forEach(box => {
        const { x_min, y_min, x_max, y_max, class_name, confidence } = box;
        const width = x_max - x_min;
        const height = y_max - y_min;

        if (confidence + 0.01 < Number((sliderConfidence / 100).toFixed(2))) {
          return;
        }

        if (labelColors[class_name]) {
          context.fillStyle = labelColors[class_name];
          context.strokeStyle = labelColors[class_name];
        }

        // Fill the bounding box area with a semi-transparent color
        context.globalAlpha = 0.2;
        context.fillRect(x_min, y_min, width, height);
        context.globalAlpha = 1.0;

        context.lineWidth = 1;
        context.strokeRect(x_min, y_min, width, height);

        const label = `${class_name} ${Math.round(confidence * 100)}%`;
        context.font = '13px Arial';
        context.fillStyle = 'black'; // Text color

        const textWidth = context.measureText(label).width;
        const textHeight = 15; // Approximate text height

        // Adjust text position if it's near the edge
        let textX = x_min;
        let textY = y_min;
        if (textX + textWidth > canvas.width) {
          textX = canvas.width - textWidth + 5;
        }
        if (textY - textHeight < 0) {
          textY = y_min + textHeight + 5;
        }

        // Draw background for text
        context.fillStyle = labelColors[class_name];
        context.fillRect(textX, textY - textHeight, textWidth, textHeight);

        // Draw text
        context.fillStyle = 'black';
        context.fillText(label, textX, textY);
      });
    };

    image.src = imageUrl;
  }, [imageUrl, boxes, labelColors, sliderConfidence]);

  return <canvas ref={canvasRef} />;
};

export default BoundingBoxCanvas;
